25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.CityOwnerLimitException;
35	import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * The maximum number of owners that may be registered on any single day (by registration date).
64	     * Once this many owners already carry today's registration date, further creation is rejected.
65	     */
66	    private static final int MAX_OWNERS_PER_DAY = 20;
67	
68	    /**
69	     * The maximum number of owners permitted in any single city. Once a city already contains
70	     * this many owners, creating a further owner in that city is rejected. Cities are matched
71	     * ignoring letter case.
72	     */
73	    private static final int MAX_OWNERS_PER_CITY = 8;
74	
75	    /**
76	     * The number of owners, counted from the very first ever created, that receive the
77	     * {@code FOUNDING} membership tier. Owners created once this many already exist receive
78	     * the {@code STANDARD} tier instead.
79	     */
80	    private static final int FOUNDING_MEMBERSHIP_LIMIT = 100;
81	
82	    private final ClinicService clinicService;
83	
84	    private final OwnerMapper ownerMapper;
85	
86	    private final PetMapper petMapper;
87	
88	    private final VisitMapper visitMapper;
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper) {
94	        this.clinicService = clinicService;
95	        this.ownerMapper = ownerMapper;
96	        this.petMapper = petMapper;
97	        this.visitMapper = visitMapper;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        HttpHeaders headers = new HttpHeaders();
129	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
130	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
131	        if (owner.getRegistrationDate() == null) {
132	            owner.setRegistrationDate(LocalDate.now());
133	        }
134	        if (isDailyRegistrationLimitReached()) {
135	            throw new DailyOwnerRegistrationLimitException(
136	                "The maximum of " + MAX_OWNERS_PER_DAY
137	                    + " owners that may be registered today has already been reached");
138	        }
139	        if (isDuplicateTelephone(owner)) {
140	            throw new DuplicateOwnerException("An owner with telephone "
141	                + owner.getTelephone() + " already exists");
142	        }
143	        if (isDuplicateEmail(owner)) {
144	            throw new DuplicateOwnerException("An owner with email "
145	                + owner.getEmail() + " already exists");
146	        }
147	        if (isCityOwnerLimitReached(owner.getCity())) {
148	            throw new CityOwnerLimitException("The city " + owner.getCity()
149	                + " already contains the maximum of " + MAX_OWNERS_PER_CITY + " owners");
150	        }
151	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
152	        owner.setMembershipNumber(membershipNumber);
153	        owner.setMembershipTier(membershipNumber <= FOUNDING_MEMBERSHIP_LIMIT ? "FOUNDING" : "STANDARD");
154	        owner.setCity(resolveCity(owner.getCity()));
155	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
156	        this.clinicService.saveOwner(owner);
157	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
158	        headers.setLocation(UriComponentsBuilder.newInstance()
159	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
160	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    /**
164	     * Determines whether the maximum number of owner registrations permitted for today has
165	     * already been reached. Owners are counted by registration date, comparing against the
166	     * current day, so the limit resets at midnight.
167	     *
168	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_DAY} owners already carry today's
169	     *         registration date
170	     */
171	    private boolean isDailyRegistrationLimitReached() {
172	        LocalDate today = LocalDate.now();
173	        long registeredToday = this.clinicService.findAllOwners().stream()
174	            .filter(existing -> today.equals(existing.getRegistrationDate()))
175	            .count();
176	        return registeredToday >= MAX_OWNERS_PER_DAY;
177	    }
178	
179	    /**
180	     * Determines whether the given city already contains the maximum number of owners permitted
181	     * per city. Owners are counted by matching their city ignoring letter case. A {@code null}
182	     * city is never considered to have reached the limit.
183	     *
184	     * @param city the city of the owner about to be created
185	     * @return {@code true} if at least {@link #MAX_OWNERS_PER_CITY} owners already reside in the
186	     *         given city
187	     */
188	    private boolean isCityOwnerLimitReached(String city) {
189	        if (city == null) {
190	            return false;
191	        }
192	        long ownersInCity = this.clinicService.findAllOwners().stream()
193	            .filter(existing -> existing.getCity() != null
194	                && existing.getCity().equalsIgnoreCase(city))
195	            .count();
196	        return ownersInCity >= MAX_OWNERS_PER_CITY;
197	    }
198	
199	    /**
200	     * Determines whether any other owner already uses the candidate's telephone number.
201	     * The comparison ignores letter case and surrounding or repeated whitespace.
202	     *
203	     * @param candidate the owner about to be created
204	     * @return {@code true} if an owner with the same telephone is already present in the data store
205	     */
206	    private boolean isDuplicateTelephone(Owner candidate) {
207	        String telephone = normalizeTelephone(candidate.getTelephone());
208	        return this.clinicService.findAllOwners().stream()
209	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
210	    }
211	
212	    /**
213	     * Canonicalises a telephone number by stripping every character that is not a digit
214	     * (for example spaces, dashes and parentheses), so that {@code "(613) 555-0100"} and
215	     * {@code "6135550100"} are treated as the same number. This is the form persisted for
216	     * an owner and used for the telephone-uniqueness check.
217	     *
218	     * @param telephone the raw telephone value, possibly {@code null}
219	     * @return the digits-only telephone, or {@code null} if {@code telephone} was {@code null}
220	     */
221	    private static String normalizeTelephone(String telephone) {
222	        if (telephone == null) {
223	            return null;
224	        }
225	        return telephone.replaceAll("[^0-9]", "");
226	    }
227	
228	    /**
229	     * Determines whether any other owner already uses the candidate's email address.
230	     * An absent or blank email is never considered a duplicate. The comparison ignores
231	     * letter case and surrounding or repeated whitespace.
232	     *
233	     * @param candidate the owner about to be created
234	     * @return {@code true} if an owner with the same email is already present in the data store
235	     */
236	    private boolean isDuplicateEmail(Owner candidate) {
237	        String email = normalize(candidate.getEmail());
238	        if (email == null || email.isBlank()) {
239	            return false;
240	        }
241	        return this.clinicService.findAllOwners().stream()
242	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
243	    }
244	
245	    /**
246	     * Builds the customer code for a newly created owner, formatted as
247	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
248	     * owners already present in the same city, zero-padded to four digits
249	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
250	     *
251	     * @param city the city of the owner about to be created
252	     * @return the formatted customer code
253	     */
254	    /**
255	     * Resolves the city name to store for a newly created owner. The supplied city is
256	     * normalised to title case (each word's first letter upper-cased, the rest lower-cased),
257	     * so that {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}.
258	     * However, if an owner already exists in that city (matched ignoring letter case), that
259	     * existing owner's exact spelling of the city is reused instead, so a single canonical
260	     * spelling is kept per city (for example an existing {@code "McFarland"} is preserved
261	     * rather than being flattened to {@code "Mcfarland"}).
262	     *
263	     * @param city the raw city supplied for the owner about to be created
264	     * @return the existing owner's spelling if the city is already known, otherwise the
265	     *         title-cased city; {@code null} if {@code city} was {@code null}
266	     */
267	    private String resolveCity(String city) {
268	        if (city == null) {
269	            return null;
270	        }
271	        return this.clinicService.findAllOwners().stream()
272	            .map(Owner::getCity)
273	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
274	            .findFirst()
275	            .orElseGet(() -> titleCase(city));
276	    }
277	
278	    /**
279	     * Converts a city name to title case: each whitespace-separated word has its first letter
280	     * upper-cased and its remaining letters lower-cased, while the original whitespace is left
281	     * untouched. For example {@code "san   FRANCISCO"} becomes {@code "San   Francisco"}.
282	     *
283	     * @param city the city to title-case
284	     * @return the title-cased city
285	     */
286	    private static String titleCase(String city) {
287	        StringBuilder result = new StringBuilder(city.length());
288	        boolean startOfWord = true;
289	        for (int i = 0; i < city.length(); i++) {
290	            char c = city.charAt(i);
291	            if (Character.isWhitespace(c)) {
292	                startOfWord = true;
293	                result.append(c);
294	            } else if (startOfWord) {
295	                result.append(Character.toTitleCase(c));
296	                startOfWord = false;
297	            } else {
298	                result.append(Character.toLowerCase(c));
299	            }
300	        }
301	        return result.toString();
302	    }
303	
304	    private String nextCustomerCode(String city) {
305	        long ownersInCity = this.clinicService.findAllOwners().stream()
306	            .filter(existing -> existing.getCity() != null
307	                && existing.getCity().equalsIgnoreCase(city))
308	            .count();
309	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
310	    }
311	
312	    /**
313	     * Canonicalises a value for duplicate detection so that comparisons ignore letter
314	     * case and surrounding or repeated whitespace. Surrounding whitespace is stripped,
315	     * any run of internal whitespace is collapsed to a single space, and the result is
316	     * lower-cased. For example {@code "  john   smith "} and {@code "John Smith"} both
317	     * normalise to {@code "john smith"}.
318	     *
319	     * @param value the raw value, possibly {@code null}
320	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
321	     */
322	    private static String normalize(String value) {
323	        if (value == null) {
324	            return null;
325	        }
326	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
327	    }
328	
329	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
330	    @Override
331	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
332	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
333	        if (currentOwner == null) {
334	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
335	        }
336	        currentOwner.setAddress(ownerFieldsDto.getAddress());
337	        currentOwner.setCity(ownerFieldsDto.getCity());
338	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
339	        currentOwner.setLastName(ownerFieldsDto.getLastName());
340	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
341	        this.clinicService.saveOwner(currentOwner);
342	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
343	    }
344	
345	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
346	    @Transactional
347	    @Override
348	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
349	        Owner owner = this.clinicService.findOwnerById(ownerId);
350	        if (owner == null) {
351	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	        }
353	        this.clinicService.deleteOwner(owner);
354	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
355	    }
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Override
359	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
360	        Owner owner = this.clinicService.findOwnerById(ownerId);
361	        if (owner == null) {
362	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
363	        }
364	        HttpHeaders headers = new HttpHeaders();
365	        Pet pet = petMapper.toPet(petFieldsDto);
366	        owner.setId(ownerId);
367	        pet.setOwner(owner);
368	        pet.getType().setName(null);
369	        this.clinicService.savePet(pet);
370	        PetDto petDto = petMapper.toPetDto(pet);
371	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
372	            .buildAndExpand(pet.getId()).toUri());
373	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
374	    }
375	
376	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
377	    @Override
378	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
379	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
380	        if (currentOwner != null) {
381	            Pet currentPet = this.clinicService.findPetById(petId);
382	            if (currentPet != null) {
383	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
384	                currentPet.setName(petFieldsDto.getName());
385	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
386	                this.clinicService.savePet(currentPet);
387	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
388	            }
389	        }
390	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
391	    }
392	
393	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
394	    @Override
395	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
396	        HttpHeaders headers = new HttpHeaders();
397	        Visit visit = visitMapper.toVisit(visitFieldsDto);
398	        Pet pet = new Pet();
399	        pet.setId(petId);
400	        visit.setPet(pet);
401	        this.clinicService.saveVisit(visit);
402	        VisitDto visitDto = visitMapper.toVisitDto(visit);
403	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
404	            .buildAndExpand(visit.getId()).toUri());
405	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
406	    }
407	
408	
409	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
410	    @Override
411	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
412	        Owner owner = this.clinicService.findOwnerById(ownerId);
413	        if (owner != null) {
414	            Pet pet = owner.getPet(petId);
415	            if (pet != null) {
416	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
417	            }
418	        }
419	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
420	    }
421	}
